import * as THREE from 'three/webgpu';
import { color, float, uniform, mix, vec3, positionLocal } from 'three/tsl';
import { createTextMesh } from '@/text';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.position.set(0, 0, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  const timelines = [];

  // ---- Prism geometry (equilateral triangular prism) ----
  const side = 1.2;
  const length = 1.8;
  const h = (Math.sqrt(3) / 2) * side;
  const triShape = new THREE.Shape();
  triShape.moveTo(-side / 2, -h / 3);
  triShape.lineTo(side / 2, -h / 3);
  triShape.lineTo(0, (2 * h) / 3);
  triShape.closePath();

  const prismGeo = new THREE.ExtrudeGeometry(triShape, {
    depth: length,
    bevelEnabled: false,
    steps: 1,
  });
  prismGeo.rotateY(Math.PI / 2);
  prismGeo.translate(0, 0, -length / 2);
  prismGeo.center();

  const prismMat = new THREE.MeshPhysicalNodeMaterial({
    color: new THREE.Color('#e8ecf2'),
    transmission: 1.0,
    thickness: 0.9,
    ior: 1.55,
    roughness: 0.08,
    clearcoat: 0.25,
    clearcoatRoughness: 0.1,
    iridescence: 1.0,
    iridescenceIOR: 1.3,
    iridescenceThicknessRange: [120, 480],
    attenuationColor: new THREE.Color('#e8ecf2'),
    attenuationDistance: 2.5,
    transparent: true,
  });

  // TSL dispersion-ish tint node driven by view-relative position, applied to colorNode
  const dispersionAmount = uniform(0.18);
  const posN = positionLocal;
  const rTint = color('#ff3348');
  const gTint = color('#e8ecf2');
  const bTint = color('#9fd0ff');
  const mixFactor = posN.y.mul(0.5).add(0.5).clamp(0, 1);
  const dispersedColor = mix(mix(rTint, gTint, mixFactor), bTint, dispersionAmount.mul(2.0).clamp(0, 1));
  prismMat.colorNode = dispersedColor;

  const prismMesh = new THREE.Mesh(prismGeo, prismMat);
  prismMesh.rotation.set(0, THREE.MathUtils.degToRad(20), THREE.MathUtils.degToRad(12));
  prismMesh.position.set(0, 0, 0);
  group.add(prismMesh);

  // ---- Emissive core (octahedron) ----
  const coreGeo = new THREE.OctahedronGeometry(0.35, 0);
  const coreMat = new THREE.MeshStandardNodeMaterial({
    color: new THREE.Color('#ff2a38'),
    emissive: new THREE.Color('#ff2a38'),
    emissiveIntensity: 2.2,
    roughness: 0.4,
    metalness: 0.1,
  });
  const coreMesh = new THREE.Mesh(coreGeo, coreMat);
  coreMesh.position.set(0, 0, 0);
  group.add(coreMesh);

  // ---- Lights ----
  const rimLight = new THREE.DirectionalLight(new THREE.Color('#9fc4ff'), 3.0);
  rimLight.position.set(-2.5, 1.0, -2.0);
  group.add(rimLight);

  const fillLight = new THREE.PointLight(new THREE.Color('#e8ecf2'), 0.8, 6);
  fillLight.position.set(1.5, 1.5, 2.0);
  group.add(fillLight);

  const coreLight = new THREE.PointLight(new THREE.Color('#ff2a38'), 1.2, 3);
  coreLight.position.set(0, 0, 0);
  group.add(coreLight);

  // ---- Caustic streak plane on floor ----
  const causticGeo = new THREE.PlaneGeometry(2.4, 0.5, 16, 4);
  const causticMat = new THREE.MeshBasicNodeMaterial({
    transparent: true,
    opacity: 0.35,
    depthWrite: false,
  });
  const capos = positionLocal;
  const causticU = capos.x.div(2.4).add(0.5).clamp(0, 1);
  const causticStop1 = color('#ff2a38');
  const causticStop2 = color('#e8ecf2');
  const causticStop3 = color('#9fb0c4');
  const mix1 = causticU.smoothstep(0.0, 0.5);
  const mix2 = causticU.smoothstep(0.5, 1.0);
  const causticColor = mix(mix(causticStop1, causticStop2, mix1), causticStop3, mix2);
  causticMat.colorNode = causticColor;
  const causticMesh = new THREE.Mesh(causticGeo, causticMat);
  causticMesh.rotation.x = -Math.PI / 2;
  causticMesh.position.set(0, -1.1, 0);
  group.add(causticMesh);

  // ---- Text ----
  const headline = createTextMesh(ctx.fontAtlas, {
    text: 'Light, machined.',
    fontFamily: 'Lora',
    fontSize: 68,
    fontWeight: 600,
    letterSpacing: -0.005,
    lineHeight: 1.1,
    color: '#e8ecf2',
  });
  headline.position.set(0, -1.75, 0);
  group.add(headline);

  const caption = createTextMesh(ctx.fontAtlas, {
    text: 'SAPPHIRE OVER DIAL / ZERO DISTORTION',
    fontFamily: 'JetBrains Mono',
    fontSize: 18,
    fontWeight: 400,
    letterSpacing: 0.08,
    lineHeight: 1.4,
    color: '#9fb0c4',
  });
  caption.position.set(0, -2.25, 0);
  group.add(caption);

  // ---- Cinematic primitive: depth-rotate on hover ----
  ctx.primitives['depth-rotate'](prismMesh, { maxDeg: 10, trigger: 'hover' });

  // ---- Hover / pointer handlers for weighted-settle & caustic elongation ----
  const baseRotX = prismMesh.rotation.x;
  const baseRotZ = prismMesh.rotation.z;
  const baseCausticScaleX = causticMesh.scale.x;

  function onPointerOver() {
    const tl = gsap.timeline();
    tl.to(prismMesh.scale, { x: 1.04, y: 1.04, z: 1.04, duration: 0.35, ease: 'cubic-bezier(0.215,0.61,0.355,1)' });
    tl.to(causticMesh.scale, { x: baseCausticScaleX * 1.08, duration: 0.35, ease: 'cubic-bezier(0.215,0.61,0.355,1)' }, 0);
    timelines.push(tl);
  }

  function onPointerOut() {
    const tl = gsap.timeline();
    tl.to(prismMesh.scale, { x: 1.0, y: 1.0, z: 1.0, duration: 0.9, ease: 'cubic-bezier(0.165,0.84,0.44,1)' });
    tl.to(causticMesh.scale, { x: baseCausticScaleX, duration: 0.9, ease: 'cubic-bezier(0.165,0.84,0.44,1)' }, 0);
    timelines.push(tl);
  }

  group.userData.handlers = {
    onPointerOver,
    onPointerOut,
  };

  group.userData.cleanup = () => {
    timelines.forEach((tl) => tl.kill());
    prismGeo.dispose();
    prismMat.dispose();
    coreGeo.dispose();
    coreMat.dispose();
    causticGeo.dispose();
    causticMat.dispose();
    if (headline.geometry) headline.geometry.dispose();
    if (headline.material) headline.material.dispose();
    if (caption.geometry) caption.geometry.dispose();
    if (caption.material) caption.material.dispose();
  };

  return group;
}
